+                match fs::canonicalize(parent) {
+                    Ok(path) => return Ok(path.starts_with(root) && false),
+                    Err(parent_error) if parent_error.kind() == io::ErrorKind::NotFound => ancestor = parent,
+                    Err(_) => return Err(ContextErrorCode::FilesystemError),
